import Image from "next/image";
import Link from "next/link";

const STRAPI_URL = "http://localhost:1337";

interface HeroProps {
  data: {
    id: number;
    // NOMBRES NUEVOS basados en tu captura:
    hero_title: string;
    hero_descrip: string;
    hero_cta_descrip: string;
    hero_image: {
      url: string;
      alternativeText: string;
    } | null;
  };
}

export default function HeroSection({ data }: HeroProps) {
  // Construimos la URL de la imagen
  const imageUrl = data.hero_image ? `${STRAPI_URL}${data.hero_image.url}` : null;

  return (
    <section className="container mx-auto w-fulltext-white py-20 px-6 text-center flex">
      <div className="left-side w-1/2">
        <h1 className="text-5xl font-bold mb-6">{data.hero_title}</h1>

        {/* Usamos los nuevos nombres de variables */}
        <p className="text-xl text-gray-300 mb-8">{data.hero_descrip}</p>

        <div className="flex justify-center gap-4">
          <Link
            href="#comprar"
            className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-8 rounded-full transition"
          >
            Comprar ahora
          </Link>
          <Link
            href="#vender"
            className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-8 rounded-full transition"
          >
            Vender ahora
          </Link>
        </div>
        <p className="text-lg text-gray-300 mb-8 py-8">{data.hero_cta_descrip}</p>
      </div>

      <div className="right-side w-1/2">
        {imageUrl && (
          <div className="relative w-full h-64 md:h-96 mb-8 rounded-lg overflow-hidden">
            <img
              src={imageUrl}
              alt={data.hero_image?.alternativeText || "Hero image"}
              className="object-cover w-full h-full"
            />
          </div>
        )}
      </div>
    </section>
  );
}